mapper.select:
SELECT DISTINCT p.* FROM sys_permission p INNER JOIN sys_role_permission rp ON rp.permission_id = p.id AND rp.is_deleted = 0 AND rp.role_id IN
#{roleId}
WHERE p.is_deleted = 0 AND p.status = 'enabled' AND p.is_visible = 1 ORDER BY p.sort ASC

SELECT DISTINCT p.* FROM sys_permission p INNER JOIN sys_tenant_package_permission tpp ON tpp.permission_id = p.id AND tpp.is_deleted = 0 INNER JOIN sys_tenant t ON t.id = tpp.package_id AND t.is_deleted = 0 WHERE p.is_deleted = 0 AND p.status = 'enabled' AND p.is_visible = 1 AND t.id = #{tenantId}
AND p.realm = #{realm}
ORDER BY p.sort ASC
